(function ($, Drupal, drupalSettings) {
  Drupal.behaviors.discounted_products_variation = {
    attach: function (context) {

      class DiscountedProductsItems {
        openModal () {
          $('.discounted-products').addClass('active');
        }

        closeModal () {
          let discountedItems = $('.discounted-products__content-items');
          $('.discounted-products').removeClass('active');
          if (discountedItems.hasClass('slick-initialized')) {
            discountedItems.slick('unslick');
          }
          $('.discounted-products__content-item').remove();
        }

        countItems () {
          return $('.discounted-products__content-items .discounted-products__content-item').length;
        }
      }

      let discountedProductsItems = new DiscountedProductsItems();
      $('.discounted-products__content-close').on('click', function() {
        discountedProductsItems.closeModal();
      });

      Drupal.AjaxCommands.prototype.DiscountedProductsAjaxItemsCommand = function (ajax, response, status) {

        discountedProductsItems.openModal();
        $(document).mouseup(function (e) {
          var div = $(".discounted-products__content");
          if ($('.discounted-products').hasClass('active') && !div.is(e.target) && div.has(e.target).length === 0) {
            discountedProductsItems.closeModal();
          }
        });

        if (discountedProductsItems.countItems() > 1) {

          $('.discounted-products__content-items').slick({
            infinite: false,
            dots: false,
            slidesToShow: 1,
            slidesToScroll: 1,
            variableWidth: true,
            prevArrow: "<div class='discounted-products__slide prev'></div>",
            nextArrow: "<div class='discounted-products__slide next'></div>"
          });

        }

      }

    }
  };
})(jQuery, Drupal, drupalSettings);
