(function ($, Drupal) {

  $(document).ready(function () {
    $('#count-shops').click(function (e) {
      e.preventDefault();

      let
        idTab = '#availability-stores__tab',
        $tab = $(idTab);

      $tab.trigger('click');

      document.querySelector(idTab).scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      })
    });
  });

  $(window).on("load", function () {
    let
      searchParams = new URLSearchParams(window.location.search),
      isAvailabilityStores = searchParams.get('availability_stores');

    if (isAvailabilityStores) {
      $('#count-shops').trigger('click');
    }
  });

  Drupal.behaviors.productFull = {
    attach: function (context, settings) {

      let tabItem = $('.bookmark__tabs-item');

      // Class ProductFull.
      class ProductFull {

        // First load page active item tab.
        defaultActiveTab () {
          let current_url=window.location.href;
          let current_url_arr=current_url.split('/');
          if (current_url_arr[current_url_arr.length-1] === 'characteristic') {
            tabItem.eq(1).find('span').click();
          } else {
            tabItem.not('.hidden').eq(0).find('span').click();
          }
        }

        // Active item tab.
        activeTab (that) {
          $('.bookmark__tabs-link').removeClass('bookmark__tabs-link_active');
          $(that).find('.bookmark__tabs-link').addClass('bookmark__tabs-link_active');

          let currentTab = $(that).data('tab');
          $('.bookmark__content-tab').removeClass('active');
          $('#' + currentTab).addClass('active');
        }

        // Animate scroll tab.
        animateScroll (selector) {
          $('html,body').stop().animate({ scrollTop: $(selector).offset().top }, 500);
          e.preventDefault();
        }

        // Tabs slider.
        tabsInit () {

          let tabs_list = $('.bookmark__tabs-list.additions__tabs');
          if (window.innerWidth < 960) {

            if (!tabs_list.hasClass('slick-initialized')) {
              tabs_list.slick({
                slidesToShow: 5,
                slidesToScroll: 1,
                infinite: false,
                arrows: false,
                responsive: [
                  {
                    breakpoint: 959,
                    settings: {
                      slidesToShow: 4,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 767,
                    settings: {
                      slidesToShow: 3,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 639,
                    settings: {
                      slidesToShow: 3,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 479,
                    settings: {
                      slidesToShow: 2,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 359,
                    settings: {
                      slidesToShow: 2,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                ]
              });
            }

          } else{

            if (tabs_list.hasClass('slick-initialized')) {
              tabs_list.slick('unslick');
            }

          }

        }

        // Breadcrumb product full.
        breadcrumbsInit () {

          let breadcrumbs = $('.breadcrumbs');
          if (window.innerWidth < 640) {

            if (!breadcrumbs.hasClass('slick-initialized')) {
              breadcrumbs.slick({
                slidesToShow: 2,
                slidesToScroll: 1,
                variableWidth: true,
                arrows: false,
                infinite: false,
              });
            }

          } else{

            if (breadcrumbs.hasClass('slick-initialized')) {
              breadcrumbs.slick('unslick');
            }

          }
        }

        // Variation attributes - memory.
        // @todo - добавить проверку на кол-во элементов
        memoryListInit () {

          let memory_list = $('.good-page__memory-list .form-item__radios');

          if (window.innerWidth < 480) {

            if (!memory_list.hasClass('slick-initialized')) {
              memory_list.slick({
                slidesToShow: 5,
                slidesToScroll: 2,
                variableWidth: true,
                arrows: false,
                autoplay: false,
                infinite: false,
                responsive: [
                  {
                    breakpoint: 479,
                    settings: {
                      slidesToShow: 6,
                      slidesToScroll: 3,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 359,
                    settings: {
                      slidesToShow: 4,
                      slidesToScroll: 3,
                      variableWidth: true,
                    }
                  },
                ]
              });
            }

          } else {

            if (memory_list.hasClass('slick-initialized')) {
              memory_list.slick('unslick');
            }

          }

        }

        // Variation attributes - color.
        // @todo - добавить проверку на кол-во элементов
        colorListInit () {

          let color_list = $('.good-page__colors-list .form-item__radios');

          if (window.innerWidth < 480) {

            if (!color_list.hasClass('slick-initialized')) {
              color_list.slick({
                slidesToShow: 5,
                slidesToScroll: 2,
                variableWidth: true,
                arrows: false,
                autoplay: false,
                infinite: false,
                responsive: [
                  {
                    breakpoint: 479,
                    settings: {
                      slidesToShow: 8,
                      slidesToScroll: 3,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 359,
                    settings: {
                      slidesToShow: 7,
                      slidesToScroll: 3,
                      variableWidth: true,
                    }
                  },
                ]
              });
            }

          } else {

            if (color_list.hasClass('slick-initialized')) {
              color_list.slick('unslick');
            }

          }

        }

        // Mobile data first init.
        mobileDataInit() {

          // Clear elements.
          $('.product-full__mobile-data').empty();
          // $('.product-full__mobile-data__bottom').empty();

          if (window.innerWidth < 960) {

            // Title.
            $('.good-page__description .good-page__description-title').clone().appendTo('.product-full__mobile-data');

            // Attributes product.
            //$('.good-page__description .good-page__description-characteristics').clone().appendTo('.product-full__mobile-data');

            // Status and SKU product.
            $('.good-page__description .good-page__schilds').clone().appendTo('.product-full__mobile-data');

            // Rating.
            $('.good-page__description .product-feedback').clone().appendTo('.product-full__mobile-data .good-page__schilds');

            // Favorites and Compare.
            $('.good-page__description .good-page__action').clone().appendTo('.product-full__mobile-data .good-page__schilds');

            // List of active promotions.
            $('.product_stocks').clone().appendTo('.product-full__mobile-data');

            // Price info.
            // $('.good-page__description .good-page__price-info').clone().appendTo('.product-full__mobile-data__bottom');

            // Buying buttons product.
            // $('.good-page__description .good-page__buying').clone().appendTo('.product-full__mobile-data__bottom');

            // Click button add to cart for mobile device.
            // $('.product-full__mobile-data__bottom .product-buy__submit-clone').on('click', function(e) {
            //   $('.good-page__description .good-page__buying .product-buy__submit-clone .btn').eq(0).once().click();
            // });

            // One click order for mobile.
            // $('.product-full__mobile-data__bottom .good-page__buy-one-click').on('click', function(e) {
            //   e.preventDefault();
            //   $('.good-page__buying .good-page__buy-one-click').eq(0).click();
            // });

            // Discount modal window for mobile.
            $('.product-full__mobile-data .good-page__price-discounts').on('click', function(e) {
              e.preventDefault();
              $('.good-page__description .good-page__price-discounts a').eq(0).click();
            });

          }
        }

        // Promotion slider for mobile.
        // @todo - добавить проверку на кол-во элементов
        promotionMobileInit () {

          let promo_list = $('.product-full__mobile-data .good-page__promo-list ul');
          if (window.innerWidth < 640) {
            if (!promo_list.hasClass('slick-initialized')) {
              promo_list.slick({
                slidesToShow: 2,
                slidesToScroll: 1,
                variableWidth: true,
                arrows: false,
                autoplay: false,
                infinite: false,
                responsive: [
                  {
                    breakpoint: 479,
                    settings: {
                      slidesToShow: 1,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                  {
                    breakpoint: 359,
                    settings: {
                      slidesToShow: 1,
                      slidesToScroll: 1,
                      variableWidth: true,
                    }
                  },
                ]
              });
            }

          } else {
            if (promo_list.hasClass('slick-initialized')) {
              promo_list.slick('unslick');
            }
          }

        }

        // Accessories slider for mobile.
        accessoriesTabInit() {

          let accessories_list = $('.view-accessories .catalog__grid');
          if (window.innerWidth < 480) {
            if (!accessories_list.hasClass('slick-initialized')) {
              accessories_list.slick({
                slidesToShow: 1,
                slidesToScroll: 1,
                variableWidth: true,
                arrows: false,
                autoplay: false,
                infinite: false,
              });
            }

          } else {
            if (accessories_list.hasClass('slick-initialized')) {
              accessories_list.slick('unslick');
            }
          }

        }

        // Product Gallery init for mobile device.
        productImagesGalleryInit() {

          // Get title.
          let product_title = $('.product-full__top .good-page__description-title').contents().first().text().trim();
          let product_char = $('.product-full__top .good-page__description-characteristics').text();

          // Get title for discount.
          if (product_title.length === 0) {
            product_title = $('.discounted-full .good-page__description-title').text();
          }

          // Get list images.
          let product_list_img = $('.product-gallery .product-gallery__nav .product-gallery__nav-item');
          product_list_img.each(function(i, el) {
            let current_path_img = $(el).find('a').attr('href');
          });

          // Append title for variation.
          $('.product-images__mobile .product-images__description').text(product_title);
          $('.product-images__mobile .product-images__characteristics').text(product_char);

          if (product_list_img.length > 0) {

            let big_images = '<ul class="product-images__big-list">'; // Data list for Big images.
            let nav_images = '<ul class="product-images__nav-list">'; // Data list for Nav images.

            // Generate data images.
            product_list_img.each(function(i, el) {
              let current_path_img = $(el).find('a').attr('href');

              // Big images.
              big_images += '<li>';
              big_images += '<img src="' + current_path_img + '" alt="' + product_title + '">';
              big_images += '</li>';

              // Nav images.
              nav_images += '<li>';
              nav_images += '<img src="' + current_path_img + '" alt="' + product_title + '">';
              nav_images += '</li>';

            });

            big_images += '</ul>';
            nav_images += '</ul>';

            // Append list images for big images.
            $('.product-images__big').empty().append(big_images);

            // Append list images for nav images.
            $('.product-images__nav').empty().append(nav_images);

          }

        }

        // Product Gallery for mobile device.
        productImagesGalleryMobile() {

          let images_big_list = $('.product-images__big-list');
          let images_nav_list = $('.product-images__nav-list');

          if (window.innerWidth < 480) {

            if (!images_big_list.hasClass('slick-initialized')) {
              images_big_list.slick({
                slidesToShow: 1,
                slidesToScroll: 1,
                arrows: false,
                infinite: true,
                asNavFor: '.product-images__nav-list'
              });
            }

            if (!images_nav_list.hasClass('slick-initialized')) {

              let icon_arrow = '<svg width="7" height="16" viewBox="0 0 10 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.72262 0.390625L0.113281 7.99996L7.72262 15.6093L9.60795 13.724L3.88395 7.99996L9.60795 2.27596L7.72262 0.390625Z" fill="#000000"/></svg>';

              images_nav_list.slick({
                slidesToShow: 4,
                slidesToScroll: 1,
                asNavFor: '.product-images__big-list',
                dots: false,
                variableWidth: true,
                centerMode: false,
                focusOnSelect: true,
                infinite: true,
                appendArrows: '.product-images__arrows',
                prevArrow: '<div class="product-images__arrow-prev">' + icon_arrow + '</div>',
                nextArrow: '<div class="product-images__arrow-next">' + icon_arrow + '</div>',
                responsive: [
                  {
                    breakpoint: 359,
                    settings: {
                      arrows: false,
                    }
                  },
                ]
              });
            }

            $('body').addClass('active');
            $('.product-images__mobile').addClass('active');

          } else {

            if (images_big_list.hasClass('slick-initialized')) {
              images_big_list.slick('unslick');
            }

            if (images_nav_list.hasClass('slick-initialized')) {
              images_nav_list.slick('unslick');
            }

          }

        }

        // Product Gallery close for mobile device.
        productImagesGalleryClose() {
          $('.product-images__big-list').slick('unslick');
          $('.product-images__nav-list').slick('unslick');
          $('body').removeClass('active');
          $('.product-images__mobile').removeClass('active');
        }

        // Replace text for discount link.
        replaceTextDiscount() {
          $('.product-full__mobile-data .good-page__price-discounts a').text('Есть уценка');
        }

      }

      let productFull = new ProductFull();

      // Gallery mobile init for mobile device.
      // $('.product-gallery__nav-item img').once('productImagesInit').on('click', function() {
      //   productFull.productImagesGalleryInit();
      //   productFull.productImagesGalleryMobile();
      // });

      $('.product-gallery__image-product').once('productImagesInit').on('click', function() {
        productFull.productImagesGalleryInit();
        productFull.productImagesGalleryMobile();
      });

      // Gallery mobile close for mobile device.
      $('.product-images__close').once('productImagesClose').on('click', function() {
        productFull.productImagesGalleryClose();
      });

      tabItem.once().on('click', function () {
        productFull.activeTab($(this));
      });
      window.addEventListener('load', function () {
        productFull.defaultActiveTab();
      }, false);

      // Product reviews.
      $('.product-feedback__reviews').once().on('click', function() {
        if ($('#reviews_ratings').length !== 0) {
          $('.bookmark__tabs-item.reviews-ratings').click();
          productFull.animateScroll('#reviews_ratings');
        }
      });

      // First init
      $('body').once('productFullInit').each(function() {
        productFull.breadcrumbsInit();
        productFull.tabsInit();
        // productFull.memoryListInit();
        // productFull.colorListInit();
        productFull.mobileDataInit();
        productFull.promotionMobileInit();
        // productFull.accessoriesTabInit();
      });

      // Action resize.
      $(window).once('productFullResize').resize(function() {
        productFull.breadcrumbsInit();
        productFull.tabsInit();
        // productFull.memoryListInit();
        // productFull.colorListInit();
        productFull.mobileDataInit();
        productFull.promotionMobileInit();
        // productFull.accessoriesTabInit();
      });

      // Replace text for discount in mobile version.
      if (window.innerWidth < 960) {
        productFull.replaceTextDiscount();
      }

      $(window).resize(function() {
        productFull.replaceTextDiscount();
      });

    }
  };

})(jQuery, Drupal);

(function ($) {
  Drupal.behaviors.productBuyCloneBtn = {
    attach: function (context, settings) {
      $('.product-buy__submit-clone').once('productBuyCloneBtn').each(function () {
        var cloneWrapper = $(this);
        var cloneBtn = '';
        // $('.product-buy__submit-clone .product-buy__submit-btn');
        var originBtn = $('.product-buy__form .form-submit');
        var originLink = $('.product-buy__row .inform-about-availability-submit:not(.product-buy__submit-btn)');
        var modalRoute = originLink.data('modal-route');

        if (originBtn.length) {
          var text = originBtn.val();
          cloneBtn = '<button class="btn btn--dark product-buy__submit-btn">' + text + '</button>';
          cloneWrapper.html(cloneBtn);
        } else if (originLink.length > 0) {
          cloneWrapper.find('.inform-about-availability-submit').remove();
          cloneWrapper.html(originLink.addClass('product-buy__submit-btn'));
        }
        if (modalRoute !== undefined) {
          var myAjaxObject = Drupal.ajax({
            url: modalRoute,
            dialogType: 'modal',
          });

          originLink.click(function () {
            myAjaxObject.execute();
          });
        }
      });
    }
  };

  Drupal.behaviors.cloneBtn = {
    attach: function (context, settings) {
      $('.product-buy__submit-clone .product-buy__submit-btn').once('cloneBtn').each(function () {
        $(this).on('click', function () {
          var btn = $(this).closest('.product-full').find('form .form-submit');
          btn.trigger('click');
        });
      });

    }
  };

  Drupal.behaviors.headerClone = {
    attach: function (context, settings) {
      $('.clone-product-buy__submit-btn').once('headerClone').each(function () {
        $(this).on('click', function (e) {
          e.preventDefault();
          let btn = $(this).closest('.product-full').find('.product-buy__submit-clone .product-buy__submit-btn')[0];
          $(btn).trigger('click');
        });
      });
    }
  };

  Drupal.behaviors.productPickupFilter = {
    attach: function (context, settings) {
      var shopWrapper = $('.shop-list');

      shopWrapper.once('pickupFilter').each(function (i, el) {
        var search = $('.shop-list__search-form input[type="text"]', el);
        var shopTable = $('.shop-list__table', el);
        var shopTableGroup = $('.shop-list__table-group', el);

        search.on('input', function () {
          var query = $(this).val().toLowerCase();
          var emptyTable = 0;

          shopTableGroup.each(function (i, el) {
            var shopList = $('.shop-item:not(.city-filtered)', el);

            var filteredList = shopList.filter(function (i, el) {
              var shopName = $('.views-field-title', el).text().toLowerCase() + ' ';
              var shopMetro = '';

              $('.metro-station__name', el).each(function (i, el) {
                shopMetro += $(el).text().toLowerCase() + ' ';
              });

              var summary = shopName + shopMetro;

              return summary.indexOf(query) !== -1;
            });

            shopList.addClass('query-filtered');
            filteredList.removeClass('query-filtered');

            $(el)[!filteredList.length ? 'addClass' : 'removeClass']('hide');

            if (!filteredList.length) {
              emptyTable += 1;
            }
          });
          shopTable[emptyTable === shopTableGroup.length ? 'addClass' : 'removeClass']('is-empty');
        });
      });
    }
  };

  Drupal.behaviors.pickupChooseCity = {
    attach: function (context, settings) {
      var wrapper = $('.shop-list__choose-city');

      wrapper.once('chooseCity').each(function (i, el) {
        var selectBtn = $('.shop-list__choose-city-current', el);
        var cityItem = $('.shop-list__choose-city-dropdown-item a', el);
        var shopList = $('.shop-list__table tbody tr');
        var shopTable = $('.shop-list__table');
        var shopTableGroup = $('.shop-list__table-group');
        var search = $('.shop-list__search-form input[type="text"]');

        selectBtn.on('click', function () {
          wrapper.toggleClass('expand');
        });

        cityItem.on('click', function () {
          var cityName = $(this).data('city');
          var cityText = $(this).text();
          var emptyTable = 0;

          selectBtn.text(cityText);

          if (cityName === 'all') {
            shopList.removeClass('city-filtered');
          } else {
            var filteredList = shopList.filter(function (i, el) {
              return $(el).data('city-name') === cityName;
            });
            shopList.addClass('city-filtered');
            filteredList.removeClass('city-filtered');
          }

          shopTableGroup.each(function (i, el) {
            var shopList = $('.shop-item', el);

            var filteredList = shopList.filter(function (i, el) {
              return $(el).hasClass('city-filtered') || $(el).hasClass('query-filtered');
            });

            $(el)[filteredList.length === shopList.length ? 'addClass' : 'removeClass']('hide');

            if (filteredList.length === shopList.length) {
              emptyTable += 1;
            }
          });

          shopTable[emptyTable === shopTableGroup.length ? 'addClass' : 'removeClass']('is-empty');
          search.trigger('input');

          wrapper.removeClass('expand');

          return false;
        });

        $(document).mouseup(function (e) {
          if (!wrapper.is(e.target) && wrapper.has(e.target).length === 0) {
            wrapper.removeClass('expand');
          }
        });
      });
    }
  };

  Drupal.behaviors.chooseShop = {
    attach: function (context, settings) {
      $('.choose-shop__btn').once('chooseShop').each(function (i, el) {
        $(this).click(function (e) {
          e.preventDefault();
          $.cookie('chosen-shop', $(this).data('code'), {expire: '', domain: '', path: '/'});
          //добавляем сообщение о добавлении товара в сравнение
          $('.messages-region').html('<div><div id="messages-wrap" class="messages-wrap"><div role="contentinfo" aria-label="Статус">' +
            '<ul class="messages__items">' +
            '<li class="messages__items-item status">' +
            '<div class="messages__items-item__content">' +
            '<div class="messages__items-close"></div>' +
            '<div class="messages__item-text">' +
            'Магазин выбран для самовывоза' + '</div>' +
            '</div>' +
            '</li></ul></div></div></div>');
          Drupal.attachBehaviors($('.messages-region'));
        });
      });
      $('.product-buy__row_color-options .color-choise__options-custom').click(function () {
        $('.messages-region').children().remove();
      });
    }
  };

})(jQuery);
