/**
 * Функция загрузки карты магазинов и переключения форм.
 */
var myMap;
var myPlacemarkWithContent;

function initMapStores() {
  (function ($) {
    ymaps.ready(function () {
      var listShop = $('.shop-item:not(.hide)').filter(function () {
        return $(this).data('geolat')
      });
      var listShopAvailability = $('.bookmark__content-tab .shop-item:not(.hide)').filter(function () {
        return $(this).data('geolat')
      });
      var listShopWrapper = $('.shop-list__table');
      var markers = new ymaps.Clusterer({
        hasBalloon: false,
//        gridSize: 128,
//        clusterIconLayout: ymaps.templateLayoutFactory.createClass('<div class="clusterCustom"><div class="clusterCustom__bg"></div> <div class="clusterCustom__count">{{ properties.geoObjects.length }}</div> </div>'),
//        clusterIconShape: {
//          type: 'Rectangle',
//          coordinates: [[0, 0], [48, 48]]
//        }
      });
      var prevMarker = null;
      var firstShop = listShop.eq(0);
      var coordCenter = [$(firstShop).data('geolat'), $(firstShop).data('geolong')];

      var smallMarker = {
        iconImageHref: 'assets/map-pointer-519ae3ca57b3.png',
        iconImageSize: [42, 54],
        iconImageOffset: [-24, -54],
      };

      var bigMarker = {
        iconImageHref: 'assets/map-pointer-519ae3ca57b3.png',
        iconImageSize: [42, 54],
        iconImageOffset: [-24, -54],
      };

      // Active shop form action Map balloon
      function openShopItemFromMap(nid) {
        var currentShop = listShop.filter('[data-nid="' + nid + '"]');

        let itemShopIdCity = $(currentShop).parent().data('city');
        $('.page-with-shops_select-city .bookmark__tabs-item').each(function (){
          if ($(this).data('city') == itemShopIdCity) $(this).trigger('click');
        })

        currentShop.closest('.shop-list__table').addClass('shop-list__table--active')
        currentShop.addClass('active');
        myMap.setCenter([currentShop.data('geolat'), currentShop.data('geolong')], 14);

        document.querySelector('[data-nid="' + nid + '"]').scrollIntoView({block: "center", behavior: "smooth"});
      }

      if (myMap) {
        myMap.container.destroy();
      }

      myMap = new ymaps.Map('map-shops', {
        center: coordCenter,
        zoom: 10,
        controls: ['zoomControl']
      }, {
        searchControlProvider: 'yandex#search'
      });

      myMap.behaviors.disable('scrollZoom');
      for (var i = 0; i < listShop.length; i++) {
        var thisShop = listShop.eq(i);
        var nid = thisShop.data('nid');
        var geolat = thisShop.data('geolat');
        var geolong = thisShop.data('geolong');
        var pointType = thisShop.data('type');
        var pointBundle = thisShop.data('bundle');

        var iconImageHref;

        if (pointType == 'node') {
          iconImageHref = 'assets/map-pointer-519ae3ca57b3.png';
        } else if (pointType == 'sdek') {
          if (pointBundle == 'POSTAMAT') {
            iconImageHref = 'assets/postomatActive-c76725adfa80.png';
          } else {
            iconImageHref = 'assets/sdekActive-93c0a41f350e.png';
          }
        }

        myPlacemarkWithContent = new ymaps.Placemark([geolat, geolong], {
          idNid: nid, pointType: pointType, pointBundle: pointBundle,
        }, {
          iconLayout: 'default#image',
          iconImageHref: iconImageHref,
          iconImageSize: [42, 54],
          iconImageOffset: [-24, -54],
        });

        // Add action
        myPlacemarkWithContent.events.add('click', function (e) {
          var placemark = e.get('target');
          var nid = placemark.properties.get('idNid');
          var pointType = placemark.properties.get('pointType');
          var pointBundle = placemark.properties.get('pointBundle');

          listShop.removeClass('active');
          openShopItemFromMap(nid);

          if (pointType == 'node') {
              smallMarker.iconImageHref = 'assets/map-pointer-519ae3ca57b3.png';
              bigMarker.iconImageHref = 'assets/map-pointer-519ae3ca57b3.png';
          } else if (pointType == 'sdek') {
            if (pointBundle == 'POSTAMAT') {
              smallMarker.iconImageHref = 'assets/postomatActive-c76725adfa80.png';
              bigMarker.iconImageHref = 'assets/postomatActive-c76725adfa80.png';
            } else {
              smallMarker.iconImageHref = 'assets/sdekActive-93c0a41f350e.png';
              bigMarker.iconImageHref = 'assets/sdekActive-93c0a41f350e.png';
            }
          }

//          if (prevMarker) {
//            prevMarker.options.set(smallMarker);
//          }

          placemark.options.set(bigMarker);

          //prevMarker = placemark;

          // Reset store search bar filter actions
          Drupal.behaviors.searchShop.clearFilter();
        });
        markers.add(myPlacemarkWithContent);
      }

      var geoObjects = markers.getGeoObjects();
      var geoObjectsQuery = ymaps.geoQuery(geoObjects);
      myMap.geoObjects.add(markers);

      // Tune a map after uploading according first city data.
      // Argument window.pointsForCityMap prepares in the themes/new_os/js/shops.js:143-147 by the function preparePointsForCenterMap
//      if (Drupal.behaviors.tabContent) {
//        Drupal.behaviors.tabContent.setCenterOfMap(window.pointsForCityMap, myMap, ymaps);
//      }
//      window.allShopsMap = myMap;

//      var cityLocation = listShop.filter(function () {
//        if ($(this).data('city') == $.cookie('hua-city')) {
//          return $(this);
//        }
//      });

      //var myGeocoder = ymaps.geocode("Петрозаводск");
      //var location = ymaps.geocode($.cookie('hua-city'));

      $('.shop-item__show_more-button').on('click', function () {
        var itemShop = $(this).parents('.shop-item');
        myMap.setCenter([itemShop.data('geolat'), itemShop.data('geolong')], 14);
      });

      listShopAvailability.on('click', function () {
        var nid = $(this).data('nid');
        var pointType = $(this).data('type');
        var pointBundle = $(this).data('pointBundle');

        if (pointType == 'node') {
            smallMarker.iconImageHref = 'assets/map-pointer-519ae3ca57b3.png';
            bigMarker.iconImageHref = 'assets/map-pointer-519ae3ca57b3.png';
        } else if (pointType == 'sdek') {
          if (pointBundle == 'POSTAMAT') {
            smallMarker.iconImageHref = 'assets/postomatActive-c76725adfa80.png';
            bigMarker.iconImageHref = 'assets/postomatActive-c76725adfa80.png';
          } else {
            smallMarker.iconImageHref = 'assets/sdekActive-93c0a41f350e.png';
            bigMarker.iconImageHref = 'assets/sdekActive-93c0a41f350e.png';
          }
        }

        for (let key in markers._objects) {
          if (markers._objects[key].geoObject.properties._data.idNid == nid) {
            var activeMarker = markers._objects[key].geoObject;
          }
        }

        if (prevMarker != activeMarker) {
          listShop.removeClass('active');
          $(this).addClass('active');
          if (prevMarker) {
            prevMarker.options.set(smallMarker);
          }
          activeMarker.options.set(bigMarker);
          myMap.setCenter([$(this).data('geolat'), $(this).data('geolong')], 14);
          prevMarker = activeMarker;
        }
      });

      $('.page-with-shops_select-city .bookmark__tabs-item--active').trigger('click');
      myMap.events.add('boundschange', updateMap)

      function updateMap(e) {
        let visibleGeoObjects = geoObjectsQuery.searchIntersect(myMap);
        let city_id = $('.bookmark__tabs-item--active').data('city');
        $('.shop-list__title-group').hide();
        $('.shop-item').each(function () {
          if ($(this).parent().data('city') != city_id) {
            $(this).hide();
            $(this).parent().hide();
            for (let key in visibleGeoObjects._objects) {
              if ($(this).data("nid") == visibleGeoObjects._objects[key].properties._data.idNid) {
                $(this).show();
                $(this).parent().show();
                $('.shop-list__title-group').show();
              }
            }
          }
        })
      }
    });
  })(jQuery);
}

(function ($, Drupal) {

  /**
   * Store search object in the list
   *
   * @type {{clearFilter: Drupal.behaviors.searchShop.clearFilter, attach: Drupal.behaviors.searchShop.attach}}
   */
  Drupal.behaviors.searchShop = {
    attach: function attach(context, settings) {
      const $searchInput = $('.shop-list__search-form input[type="text"]', context);
      if($searchInput.length === 0) {
        return;
      }

      const $shopItems = $('.shop-list__table .shop-item', context);
      const filter_throttle = throttle(filter, 500);
      $searchInput.on('input', function () {
        filter_throttle();
      });

      /**
       * Filters the list of stores
       */
      function filter() {
        const regExp = new RegExp($searchInput.val(), 'gi');
        const $visibleItems = $shopItems.filter(function (index){
          return $(this).html().match(regExp) !== null;
        }).show();
        const $list = $('.shop-list__container');
        const $empty = $('.shop-list__empty');

        $shopItems.filter(function (index){
          return $(this).html().match(regExp) === null;
        }).hide();

        if ($visibleItems.length === 0) {
          $list.hide();
          $empty.show();
        }
        else {
          $empty.hide();
          $list.show();
        }

        if($('.shop-list__switch-button--map.is-active').length === 0) {
          return;
        }
      }
    },
    clearFilter: function clearFilter() {
      if(typeof this.$shopItems === 'undefined') {
        this.$shopItems = $('.shop-list__table .shop-item');
      }

      if(typeof this.$searchInput === 'undefined') {
        this.$searchInput = $('.shop-list__search-form input[type="text"]');
      }

      this.$searchInput.val('');
    }
  };

  Drupal.behaviors.shopListSwitchView = {
    attach: function (context, settings) {
      var shopList = $('.shop-list', context);

      shopList.once('switchView').each(function (i, el) {
        var viewsWrapper = $('.shop-list__container', el);
        var listViewBtn = $('.shop-list__switch-button--list', el);
        var mapViewBtn = $('.shop-list__switch-button--map', el);
        var cityFilter = $('.shop-list__choose-city');

        mapViewBtn.on('click', function () {
          viewsWrapper.addClass('shop-list__container--map-view');
          listViewBtn.removeClass('is-active');
          mapViewBtn.addClass('is-active');
          cityFilter.addClass('hide');
        });

        listViewBtn.on('click', function () {
          viewsWrapper.removeClass('shop-list__container--map-view');
          listViewBtn.addClass('is-active');
          mapViewBtn.removeClass('is-active');
          cityFilter.removeClass('hide');
          $(this).closest('.shop-items').find('.shop-item').each(function (index, value) {
            $(value).removeClass('active');
            $(value).find('.shop-item__search-button').text('Как найти');
          });
        });
      });
    }
  };

  /**
   * Throttle
   */
  function throttle(func, ms) {

    let isThrottled = false,
      savedArgs,
      savedThis;

    function wrapper() {

      if (isThrottled) { // (2)
        savedArgs = arguments;
        savedThis = this;
        return;
      }

      func.apply(this, arguments); // (1)

      isThrottled = true;

      setTimeout(function () {
        isThrottled = false; // (3)
        if (savedArgs) {
          wrapper.apply(savedThis, savedArgs);
          savedArgs = savedThis = null;
        }
      }, ms);
    }

    return wrapper;
  }

  /**
   * Инициализация карты при загрузке страницы.
   */
  Drupal.behaviors.ymapShops = {
    attach: function attach(context, settings) {
      $('.map-shops', context).once().each(function () {
        initMapStores();
      });
    }
  };

  /**
   * Реинициализая карты при обновлении вариации.
   */
  $.fn.renewMaps = function (data) {
    initMapStores();
  };

})(jQuery, Drupal);

